# test_retry.py

import pytest
from unittest.mock import Mock

from your_module import retry  # replace with the actual module name


def test_returns_value_on_first_success():
    fn = Mock(return_value="success")

    result = retry(fn)

    assert result == "success"
    fn.assert_called_once_with()


def test_retries_until_success():
    fn = Mock(side_effect=[
        ValueError("first failure"),
        RuntimeError("second failure"),
        "success",
    ])

    result = retry(fn, max_attempts=3)

    assert result == "success"
    assert fn.call_count == 3


def test_uses_default_max_attempts():
    fn = Mock(side_effect=[
        ValueError("first failure"),
        ValueError("second failure"),
        "success",
    ])

    result = retry(fn)

    assert result == "success"
    assert fn.call_count == 3


def test_reraises_last_exception_after_max_attempts():
    first_error = ValueError("first failure")
    final_error = RuntimeError("final failure")
    fn = Mock(side_effect=[first_error, final_error])

    with pytest.raises(RuntimeError) as exc_info:
        retry(fn, max_attempts=2)

    assert exc_info.value is final_error
    assert fn.call_count == 2


def test_max_attempts_one_does_not_retry():
    error = ValueError("failure")
    fn = Mock(side_effect=error)

    with pytest.raises(ValueError) as exc_info:
        retry(fn, max_attempts=1)

    assert exc_info.value is error
    assert fn.call_count == 1


@pytest.mark.parametrize("max_attempts", [0, -1])
def test_non_positive_max_attempts_does_not_call_function(max_attempts):
    fn = Mock(return_value="success")

    result = retry(fn, max_attempts=max_attempts)

    assert result is None
    fn.assert_not_called()


